<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"></head><body style="margin:0;background:#f5f1e8;color:#25251f;font-family:Arial,sans-serif;font-size:16px;line-height:1.6"><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" style="width:100%;max-width:600px;background:#fff" cellspacing="0" cellpadding="0"><tr><td style="background:#171914;color:#d1b77d;padding:28px;text-align:center"><h1 style="margin:0;font-family:Georgia,serif;font-weight:400;letter-spacing:4px">{{ $details['business']['brand_name'] }}</h1><p style="margin:8px 0 0;font-size:13px">{{ $details['business']['tagline'] }}</p></td></tr><tr><td style="padding:28px"><h2 style="font-family:Georgia,serif;font-weight:400">{{ $details['event']==='placed' ? 'Thank you for your order' : 'An update on your order' }}</h2><p>Dear {{ $details['order']['name'] }},</p><p>{{ $details['event']==='placed' ? 'We have received your order. Our team will review it and keep you informed as it moves towards your doorstep.' : 'Your order details have been updated. Here is the latest information from Rang Mahal.' }}</p><p><strong>Order reference / Tracking ID:</strong><br>{{ $details['order']['reference'] }}<br><strong>Order date:</strong> {{ $details['order']['created_at'] }}<br><strong>Order status:</strong> {{ $details['order']['status'] }}<br><strong>Payment:</strong> {{ $details['order']['payment_method']==='cod'?'Cash on delivery':'Bank transfer' }} — {{ $details['order']['payment_status'] }}</p><table width="100%" cellspacing="0" cellpadding="8" style="border-collapse:collapse"><thead><tr style="background:#f5f1e8"><th align="left">Your selection</th><th align="right">Amount</th></tr></thead><tbody>@foreach($details['items'] as $item)<tr><td style="border-bottom:1px solid #eee">{{ $item['name'] }}<br>{{ $item['variant'] }} × {{ $item['quantity'] }}@if($item['stitching_charge']>0)<br><small>Stitching included: PKR {{ number_format($item['stitching_charge'],2) }} per piece</small>@endif</td><td align="right" style="border-bottom:1px solid #eee">PKR {{ number_format($item['price']*$item['quantity'],2) }}</td></tr>@endforeach<tr><td>Delivery</td><td align="right">PKR {{ number_format($details['order']['shipping'],2) }}</td></tr><tr><td><strong>Order total</strong></td><td align="right"><strong>PKR {{ number_format($details['order']['total'],2) }}</strong></td></tr></tbody></table>@if($details['order']['courier_name'])<p><strong>Courier:</strong> {{ $details['order']['courier_name'] }}<br><strong>Courier tracking number:</strong> {{ $details['order']['courier_tracking_number'] ?: 'Awaiting assignment' }}</p>@endif @if($details['order']['estimated_delivery_date'])<p>Estimated delivery: {{ $details['order']['estimated_delivery_date'] }}</p>@endif<p style="margin:28px 0"><a href="{{ url('/track?reference='.rawurlencode($details['order']['reference'])) }}" style="background:#171914;color:#e6d1a1;text-decoration:none;padding:14px 22px;display:inline-block">Track your order</a></p><p>Enter your order reference and the email address used at checkout to securely view your order status.</p>@if($details['order']['courier_tracking_url'] && str_starts_with($details['order']['courier_tracking_url'],'https://'))<p><a href="{{ $details['order']['courier_tracking_url'] }}">View courier tracking</a></p>@endif<p>Need help? Reply to this email and include your order reference.</p><p>With warm regards,<br>The {{ $details['business']['brand_name'] }} team</p><hr style="border:0;border-top:1px solid #eee"><p style="font-size:13px">Return address: {{ $details['business']['return_address'] }}<br>{{ $details['business']['return_policy'] }}<br>{{ $details['business']['refund_conditions'] }}<br><a href="{{ url('/?policy=delivery') }}">Shipping, returns and exchange policy</a></p></td></tr><tr><td style="padding:20px;background:#f5f1e8;font-size:12px;text-align:center">This service email relates to your Rang Mahal order. It is not a marketing subscription.</td></tr></table></td></tr></table></body></html>
